-- Informatif : ces tables sont créées AUTOMATIQUEMENT par le serveur au premier appel.
CREATE TABLE IF NOT EXISTS docs (coll TEXT NOT NULL, id TEXT NOT NULL, ver INTEGER NOT NULL DEFAULT 1, data TEXT NOT NULL, PRIMARY KEY (coll, id));
CREATE TABLE IF NOT EXISTS comptes (cle TEXT PRIMARY KEY, sel TEXT NOT NULL, hash TEXT NOT NULL, prov INTEGER NOT NULL DEFAULT 0, essais INTEGER NOT NULL DEFAULT 0, verrou BIGINT NOT NULL DEFAULT 0, sv INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS audios (id TEXT PRIMARY KEY, mime TEXT NOT NULL, b64 TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS meta (k TEXT PRIMARY KEY, v TEXT NOT NULL);
